// ALTA regular-season lineup rules R1-R7. A JavaScript copy of src/rules_checker.py for n8n Code nodes.
// n8n/build_nodes.py prepends ROSTER, CONFIG and HISTORY from the project's JSON files.
// tests/test_n8n_nodes.py checks that this gives the same answers as the Python version.

const pairKey = (pair) => [...pair].sort().join('|');

function buildState(history) {
  const s = { lastLine: {}, pairLast: {}, pairRecord: {}, played: {} };
  for (const m of history.matches || []) {
    const results = m.results || [];
    m.lineup.forEach((pair, i) => {
      const line = i + 1;
      for (const pid of pair) s.played[pid] = (s.played[pid] || 0) + 1;
      if (m.provisional) return; // counts as played, but positions are tracked from the previous legal lineup
      const key = pairKey(pair);
      s.pairLast[key] = line;
      const rec = s.pairRecord[key] || (s.pairRecord[key] = [0, 0]);
      const won = i < results.length ? results[i] : null;
      if (won === true) rec[0] += 1;
      else if (won === false) rec[1] += 1;
      for (const pid of pair) s.lastLine[pid] = line;
    });
  }
  return s;
}

function pairStatus(state, pair) {
  const [w, l] = state.pairRecord[pairKey(pair)] || [0, 0];
  return w > l ? 'winning' : l > w ? 'losing' : 'none';
}

function allowedLinesForPlayer(pid, state, config) {
  const all = Array.from({ length: config.lines }, (_, i) => i + 1);
  if (!(pid in state.lastLine)) return all;
  return all.filter((x) => Math.abs(x - state.lastLine[pid]) <= config.individual_move_limit);
}

function allowedLinesForPair(pair, state, config) {
  let ok = Array.from({ length: config.lines }, (_, i) => i + 1);
  for (const pid of pair) {
    const allowed = allowedLinesForPlayer(pid, state, config);
    ok = ok.filter((x) => allowed.includes(x));
  }
  const key = pairKey(pair);
  if (key in state.pairLast) ok = ok.filter((x) => Math.abs(x - state.pairLast[key]) <= config.pair_move_limit);
  return ok;
}

function checkLineup(lineup, roster, config, available, state) {
  const v = [];
  const players = {};
  for (const p of roster.players) players[p.id] = p;
  const name = (pid) => (players[pid] ? players[pid].name : pid);

  // R1: right number of lines, right number of players on each
  if (lineup.length !== config.lines) v.push({ rule_id: 'R1', message: `Expected ${config.lines} lines, got ${lineup.length}.` });
  lineup.forEach((pair, i) => {
    if (pair.length !== config.players_per_line) {
      v.push({ rule_id: 'R1', message: `Line ${i + 1} needs ${config.players_per_line} players, got ${pair.length}.` });
    }
  });
  const everyone = lineup.flat();

  // R2: everyone is on the roster
  for (const pid of everyone) if (!players[pid]) v.push({ rule_id: 'R2', message: `${pid} is not on the roster.` });

  // R3: one line per player
  const seen = new Set();
  for (const pid of everyone) {
    if (seen.has(pid)) v.push({ rule_id: 'R3', message: `${name(pid)} is in more than one line.` });
    seen.add(pid);
  }

  // R4: everyone is confirmed available
  for (const pid of new Set(everyone)) {
    if (players[pid] && !available.has(pid)) v.push({ rule_id: 'R4', message: `${name(pid)} is not confirmed available.` });
  }

  // R5: pair movement, from the last line the pair played together
  const moves = [];
  lineup.forEach((pair, i) => {
    const line = i + 1;
    const key = pairKey(pair);
    if (pair.length === 2 && key in state.pairLast) {
      const last = state.pairLast[key];
      moves.push([pair, last, line]);
      if (Math.abs(line - last) > config.pair_move_limit) {
        v.push({
          rule_id: 'R5',
          message: `${name(pair[0])} and ${name(pair[1])} last played together at line ${last}; a pair may move only ${config.pair_move_limit} line, so line ${line} is not allowed.`,
        });
      }
    }
  });

  // R6: individual movement, from the player's own last legal line
  lineup.forEach((pair, i) => {
    const line = i + 1;
    for (const pid of pair) {
      if (pid in state.lastLine && Math.abs(line - state.lastLine[pid]) > config.individual_move_limit) {
        v.push({
          rule_id: 'R6',
          message: `${name(pid)} last played line ${state.lastLine[pid]}; a player may move only ${config.individual_move_limit} lines, so line ${line} is not allowed.`,
        });
      }
    }
  });

  // R7: sandbagging. A winning pair moved down while a losing pair moved up.
  const down = moves.filter(([p, a, b]) => b > a && pairStatus(state, p) === 'winning');
  const up = moves.filter(([p, a, b]) => b < a && pairStatus(state, p) === 'losing');
  if (down.length && up.length) {
    const w = down[0];
    const l = up[0];
    v.push({
      rule_id: 'R7',
      message: `Sandbagging: winning pair ${name(w[0][0])} and ${name(w[0][1])} moves down (line ${w[1]} to ${w[2]}) while losing pair ${name(l[0][0])} and ${name(l[0][1])} moves up (line ${l[1]} to ${l[2]}).`,
    });
  }
  return v;
}

// Does a player's time limit fit a line? A JavaScript copy of src/line_times.py for n8n Code nodes.
// Lines play two per start slot, an hour apart (every adult ALTA league). A line can run 1 to 3 hours,
// so a listed start is the earliest start. n8n/build_nodes.py prepends CONFIG.

const toMin = (hhmm) => {
  const [h, m] = hhmm.split(':');
  return Number(h) * 60 + Number(m);
};

const fmt = (minutes) => {
  const h = Math.floor(minutes / 60) % 24;
  const m = minutes % 60;
  return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`;
};

function parseWindow(text) {
  const out = { earliestStart: null, latestEnd: null };
  if (!text) return out;
  const m = /\b(after|until)\s+(\d{1,2}):(\d{2})\b/.exec(String(text).toLowerCase());
  if (m) {
    const minutes = Number(m[2]) * 60 + Number(m[3]);
    if (m[1] === 'after') out.earliestStart = minutes;
    else out.latestEnd = minutes;
  }
  return out;
}

function timeFit(window, line, firstStartMin, config) {
  const start = firstStartMin + 60 * Math.floor((line - 1) / 2);
  const hours = config.line_duration_hours;
  const short = start + Math.trunc(hours.min * 60);
  const long = start + Math.trunc(hours.max * 60);
  const w = parseWindow(window);
  const base = { line, start: fmt(start), ends_if_short: fmt(short), ends_if_long: fmt(long) };
  if (w.earliestStart !== null && start < w.earliestStart) {
    return { ...base, status: 'no', why: `starts at ${fmt(start)}, before ${fmt(w.earliestStart)}` };
  }
  if (w.latestEnd !== null) {
    if (long <= w.latestEnd) return { ...base, status: 'ok', why: `done by ${fmt(long)} even if it runs ${hours.max} hours` };
    if (short <= w.latestEnd) return { ...base, status: 'risky', why: `fits a ${hours.min}-hour line, not a long one` };
    return { ...base, status: 'no', why: `cannot finish by ${fmt(w.latestEnd)}` };
  }
  return { ...base, status: 'ok', why: 'no time limit' };
}

// ALTA lineup planner. A JavaScript copy of src/planner.py for n8n Code nodes; see that file for the design.
// Needs rules_core.js and time_fit_core.js above it, plus ROSTER, CONFIG and HISTORY.
// tests/test_n8n_nodes.py checks that this returns exactly what the Python planner returns.

const WEIGHTS = { move: 4, newcomer: 3, new_pair: 6, risky: 12, played: 1, side: 2, rank: 2, reserve: 10 };
const COMPONENTS = ['move', 'newcomer', 'new_pair', 'risky', 'played', 'side', 'rank', 'reserve'];

const cmp = (x, y) => (x < y ? -1 : x > y ? 1 : 0);
const pkey = (pair) => [...pair].sort().join('-');

function makeScorer(roster, config, state, pool, firstStart, windows, baseline, ranking, reserve) {
  const n = config.lines;
  const size = config.players_per_line;
  const side = {};
  for (const p of roster.players) side[p.id] = p.side || 'either';
  const firstMin = toMin(firstStart);

  const fit = {};
  for (const p of pool) for (let line = 1; line <= n; line++) fit[`${p}|${line}`] = timeFit(windows[p] || null, line, firstMin, config);
  const allowed = {};
  for (const p of pool) allowed[p] = allowedLinesForPlayer(p, state, config).filter((line) => fit[`${p}|${line}`].status !== 'no');

  const hasBaseline = !!(baseline && baseline.length);
  const baseLine = {};
  const basePairs = new Set();
  (baseline || []).forEach((pair, i) => {
    for (const p of pair) baseLine[p] = i + 1;
    basePairs.add(pkey(pair));
  });

  const hasRanking = !!(ranking && ranking.length);
  const ideal = {};
  if (hasRanking) {
    const order = ranking.filter((p) => pool.includes(p)).concat(pool.filter((p) => !ranking.includes(p)));
    order.forEach((p, i) => { ideal[p] = Math.min(n, 1 + Math.floor(i / size)); });
  }

  function pairCost(a, b, line) {
    const c = {};
    for (const name of COMPONENTS) c[name] = 0;
    for (const p of [a, b]) {
      c.played += WEIGHTS.played * (state.played[p] || 0);
      if (hasBaseline) {
        if (p in baseLine) c.move += WEIGHTS.move * Math.abs(line - baseLine[p]);
        else c.newcomer += WEIGHTS.newcomer;
      } else if (p in state.lastLine) {
        c.move += WEIGHTS.move * Math.abs(line - state.lastLine[p]);
      }
      if (fit[`${p}|${line}`].status === 'risky') c.risky += WEIGHTS.risky;
      if (hasRanking) c.rank += WEIGHTS.rank * Math.abs(line - ideal[p]);
      if (reserve.has(p)) c.reserve += WEIGHTS.reserve;
    }
    const isNew = hasBaseline ? !basePairs.has(pkey([a, b])) : !(pairKey([a, b]) in state.pairLast);
    if (isNew) c.new_pair += WEIGHTS.new_pair;
    if (side[a] === side[b] && (side[a] === 'ad' || side[a] === 'deuce')) c.side += WEIGHTS.side;
    return c;
  }
  return { fit, allowed, pairCost };
}

function reasonsFor(a, b, line, byId, state, fit, windows) {
  const first = (pid) => byId[pid].name.split(' ')[0];
  const out = [];
  const pk = pairKey([a, b]);
  if (pk in state.pairLast) {
    const last = state.pairLast[pk];
    const [w, l] = state.pairRecord[pk] || [0, 0];
    const rec = w + l ? ` Record together: ${w}-${l}.` : '';
    if (last === line) out.push(`Same pair as before, last played line ${line}.${rec} (R5)`);
    else out.push(`Played together at line ${last}, so line ${line} is one move.${rec} (R5)`);
  } else {
    const parts = [a, b].map((p) => (p in state.lastLine ? `${first(p)} last played line ${state.lastLine[p]}` : `${first(p)} hasn't played this season`));
    out.push(`New pair. ${parts.join(', ')}; line ${line} is within two lines for each. (R6)`);
  }
  for (const p of [a, b]) {
    if (windows[p]) out.push(`${first(p)}: ${fit[`${p}|${line}`].why}.`);
  }
  return out;
}

function plan(roster, config, state, args) {
  const n = config.lines;
  const size = config.players_per_line;
  const windows = args.windows || {};
  const k = args.k === undefined || args.k === null ? 3 : args.k;
  const nodeBudget = args.node_budget === undefined || args.node_budget === null ? 200000 : args.node_budget;
  const byId = {};
  for (const p of roster.players) byId[p.id] = p;
  const reserveSet = new Set(args.reserve || []);
  const excluded = new Set(args.exclude || []);
  const pool = [...new Set([...(args.available || []), ...reserveSet])].filter((p) => !excluded.has(p) && p in byId).sort();
  const fixed = {};
  for (const [line, pair] of Object.entries(args.fixed || {})) fixed[Number(line)] = [...pair].sort();
  const { fit, allowed, pairCost } = makeScorer(roster, config, state, pool, args.first_start, windows, args.baseline, args.ranking, reserveSet);

  const cands = {};
  for (let line = 1; line <= n; line++) {
    const rows = [];
    for (let i = 0; i < pool.length; i++) {
      for (let j = i + 1; j < pool.length; j++) {
        const a = pool[i];
        const b = pool[j];
        if (line in fixed && !(fixed[line][0] === a && fixed[line][1] === b)) continue;
        if (!allowed[a].includes(line) || !allowed[b].includes(line)) continue;
        const pk = pairKey([a, b]);
        if (pk in state.pairLast && Math.abs(line - state.pairLast[pk]) > config.pair_move_limit) continue;
        const comps = pairCost(a, b, line);
        rows.push({ total: COMPONENTS.reduce((s, name) => s + comps[name], 0), a, b, comps });
      }
    }
    rows.sort((x, y) => x.total - y.total || cmp(x.a, y.a) || cmp(x.b, y.b));
    cands[line] = rows;
  }

  let best = [];
  const stats = { nodes: 0, exhausted: false, rejected: {} };
  const poolSet = new Set(pool);

  function dfs(line, used, total, chosen, compsList) {
    if (stats.exhausted) return;
    if (best.length === k && total >= best[best.length - 1].total) return;
    if (line > n) {
      const lineup = chosen.map(([a, b]) => [a, b]);
      const violations = checkLineup(lineup, roster, config, poolSet, state);
      if (violations.length) {
        for (const rid of [...new Set(violations.map((v) => v.rule_id))].sort()) stats.rejected[rid] = (stats.rejected[rid] || 0) + 1;
        return;
      }
      best.push({ total, key: lineup.map((p) => p.join('-')).join(';'), lineup, compsList: [...compsList] });
      best.sort((x, y) => x.total - y.total || cmp(x.key, y.key));
      best = best.slice(0, k);
      return;
    }
    for (const row of cands[line]) {
      stats.nodes += 1;
      if (stats.nodes > nodeBudget) {
        stats.exhausted = true;
        return;
      }
      if (used.has(row.a) || used.has(row.b)) continue;
      dfs(line + 1, new Set([...used, row.a, row.b]), total + row.total, [...chosen, [row.a, row.b]], [...compsList, row.comps]);
    }
  }
  dfs(1, new Set(), 0, [], []);

  const options = best.map((b, idx) => {
    const breakdown = {};
    for (const name of COMPONENTS) breakdown[name] = b.compsList.reduce((s, c) => s + c[name], 0);
    const lines = [];
    const warnings = [];
    b.lineup.forEach(([a, c], i) => {
      const line = i + 1;
      lines.push({
        line,
        start: fit[`${a}|${line}`].start,
        players: [a, c].map((p) => ({ id: p, name: byId[p].name })),
        reasons: reasonsFor(a, c, line, byId, state, fit, windows),
      });
      for (const p of [a, c]) {
        if (fit[`${p}|${line}`].status === 'risky') warnings.push(`${byId[p].name.split(' ')[0]} may have to leave early if line ${line} runs long.`);
        if (reserveSet.has(p)) warnings.push(`${byId[p].name} said she would play only if needed.`);
      }
    });
    const usedIds = new Set(b.lineup.flat());
    return { rank: idx + 1, lineup: b.lineup, score: b.total, breakdown, lines, bench: pool.filter((p) => !usedIds.has(p)), warnings };
  });

  const linesCounts = [];
  for (let line = 1; line <= n; line++) linesCounts.push(cands[line].length);
  let reason = null;
  if (!options.length) {
    const need = n * size;
    if (pool.length < need) reason = `Only ${pool.length} players are available and ${need} are needed.`;
    else if (stats.exhausted) reason = 'The search hit its limit before finding a legal lineup.';
    else if (linesCounts.includes(0)) reason = `No legal pair is available for line ${linesCounts.indexOf(0) + 1}.`;
    else reason = 'No combination of legal pairs works together (for example, the same players are needed on two lines, or sandbagging rule R7 blocks every order).';
  }
  return { options, pool, complete: !stats.exhausted, candidates_per_line: linesCounts, rejected_at_leaf: stats.rejected, none_reason: reason };
}

const state = buildState(HISTORY);
return $input.all().map((item) => ({ json: { scenario: item.json.scenario, ...plan(ROSTER, CONFIG, state, item.json) } }));
